-- =============================================================================
-- HarmonyLens - Inventory Management Database Schema (PostgreSQL)
-- =============================================================================
-- Users, lens catalog, imports, lots and inventory (HU06, HU11) plus the
-- supporting tables later stories depend on (points of sale, requests,
-- restock orders, dispatches, lot history). See some_info.md and project.md.
--
-- Conventions:
--   * snake_case identifiers.
--   * All PKs are UUID generated by the database.
--   * TIMESTAMPTZ for all timestamps (store in UTC).
--   * created_at / updated_at audit columns on mutable entities.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";   -- gen_random_uuid()
CREATE EXTENSION IF NOT EXISTS "citext";     -- case-insensitive email

-- -----------------------------------------------------------------------------
-- ENUM types
-- -----------------------------------------------------------------------------

-- Roles mentioned in the user stories.
CREATE TYPE user_role AS ENUM (
    'director_tecnico',        -- authorizes lots (HU06)
    'asesor_punto_venta',      -- requests lenses by formula (HU07)
    'admin_puntos_venta',      -- builds restock orders (HU08)
    'jefe_almacen',            -- imports, inventory & lot history (HU11, HU12)
    'auxiliar_bodega',         -- reception, labeling, shelving
    'admin'                    -- system administrator
);

-- Lifecycle of an imported lot.
CREATE TYPE lot_status AS ENUM (
    'pendiente_revision',      -- received & located, awaiting review
    'autorizado',              -- approved, available for dispatch
    'rechazado'                -- rejected, blocked for dispatch
);

CREATE TYPE lens_request_status AS ENUM (
    'solicitada',              -- registered, visible to warehouse
    'pendiente',               -- no stock, waiting for replenishment
    'despachada',              -- dispatched to the point of sale
    'cancelada'
);

CREATE TYPE restock_order_status AS ENUM (
    'pendiente_alistamiento',  -- created, waiting to be picked
    'alistado',
    'despachado',
    'recibido',
    'cancelado'
);

-- Events tracked in a lot's history (HU12).
CREATE TYPE lot_event_type AS ENUM (
    'recepcion',
    'etiquetado',
    'ubicacion',
    'autorizacion',
    'rechazo',
    'despacho'
);

-- =============================================================================
-- USERS
-- =============================================================================

CREATE TABLE users (
    id             UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    full_name      TEXT         NOT NULL,
    email          CITEXT       NOT NULL,   -- case-insensitive, unique
    password_hash  TEXT         NOT NULL,
    role           user_role    NOT NULL,
    -- A point-of-sale user (asesor) is tied to one point of sale.
    point_of_sale_id UUID,
    is_active      BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT users_email_key UNIQUE (email)
);

-- =============================================================================
-- ORGANIZATION: points of sale and warehouse locations
-- =============================================================================

CREATE TABLE points_of_sale (
    id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    name        TEXT        NOT NULL,
    code        TEXT        NOT NULL UNIQUE,
    address     TEXT,
    is_active   BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Now that points_of_sale exists, wire the FK from users.
ALTER TABLE users
    ADD CONSTRAINT users_point_of_sale_fk
    FOREIGN KEY (point_of_sale_id) REFERENCES points_of_sale (id)
    ON DELETE SET NULL;

-- Shelf / storage locations inside the warehouse (HU11 "ubicación en estantería").
CREATE TABLE warehouse_locations (
    id          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    code        TEXT        NOT NULL UNIQUE,   -- e.g. "A-03-12"
    description TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =============================================================================
-- LENS CATALOG  (the "referencia del lente")
-- =============================================================================
-- Each lens carries a formula split into sphere and cylinder, plus a code
-- (identifier / abbreviation) and a description tied to that code.
--
-- Rules from some_info.md:
--   * sphere   : -4.00 .. 4.00, step 0.25, either sign.
--   * cylinder :  0.00 .. 4.00 magnitude, step 0.25, stored as <= 0 (negative).
-- NUMERIC(4,2) keeps exact decimal values (double would be imprecise).
-- -----------------------------------------------------------------------------

CREATE TABLE lenses (
    id             UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    code           TEXT          NOT NULL UNIQUE,   -- system identifier / abbreviation
    description    TEXT          NOT NULL,          -- full description tied to the code
    sphere         NUMERIC(4, 2) NOT NULL,
    cylinder       NUMERIC(4, 2) NOT NULL,
    -- Minimum stock level per reference, drives the low-stock alert (HU11.2).
    min_stock      INTEGER       NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ   NOT NULL DEFAULT now(),

    -- sphere: -4.00..4.00 in 0.25 steps.
    CONSTRAINT lenses_sphere_range CHECK (sphere BETWEEN -4.00 AND 4.00),
    CONSTRAINT lenses_sphere_step  CHECK ((sphere * 100)::INTEGER % 25 = 0),
    -- cylinder: negative only, magnitude 0.00..4.00 in 0.25 steps.
    CONSTRAINT lenses_cylinder_range CHECK (cylinder BETWEEN -4.00 AND 0.00),
    CONSTRAINT lenses_cylinder_step  CHECK ((cylinder * 100)::INTEGER % 25 = 0),
    CONSTRAINT lenses_min_stock_nonneg CHECK (min_stock >= 0)
);

-- =============================================================================
-- IMPORTS & LOTS
-- =============================================================================
-- An import (arrival) documents the shipment (RN001): distributor, invoice and
-- manufacturer. Each line of the shipment becomes a lot: one lens reference,
-- with its lot number, INVIMA registration, box count and unit quantity.
-- A lot is the unit tracked through the review/authorization workflow (HU06).
-- -----------------------------------------------------------------------------

CREATE TABLE imports (
    id                UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    distributor       TEXT        NOT NULL,           -- "distribuidor" (HU06.1)
    invoice_number    TEXT,                           -- "número de factura"
    manufacturer      TEXT,                           -- "fabricante"
    notes             TEXT,
    received_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by        UUID        REFERENCES users (id) ON DELETE SET NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE lots (
    id                  UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    lot_number          TEXT        NOT NULL UNIQUE,  -- "lote" / label (etiquetado)
    import_id           UUID        REFERENCES imports (id) ON DELETE SET NULL,
    lens_id             UUID        NOT NULL REFERENCES lenses (id) ON DELETE RESTRICT,
    invima_registration TEXT        NOT NULL,         -- "registro invima"
    box_count           INTEGER     NOT NULL,         -- "cantidad de cajas"
    quantity_received   INTEGER     NOT NULL,         -- units received in this lot
    quality_notes       TEXT,                         -- "calidad con que llegaron"
    status              lot_status  NOT NULL DEFAULT 'pendiente_revision',
    location_id         UUID        REFERENCES warehouse_locations (id) ON DELETE SET NULL,
    received_at         TIMESTAMPTZ NOT NULL DEFAULT now(),

    -- Authorization decision audit (HU06.2 / HU06.3): who, when, outcome, reason.
    decided_by          UUID        REFERENCES users (id) ON DELETE SET NULL,
    decided_at          TIMESTAMPTZ,
    rejection_reason    TEXT,

    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT lots_box_count_positive CHECK (box_count > 0),
    CONSTRAINT lots_quantity_positive  CHECK (quantity_received > 0),
    -- A rejected lot must carry a non-blank reason (HU06.3).
    CONSTRAINT lots_rejection_reason_required
        CHECK (status <> 'rechazado' OR length(btrim(rejection_reason)) > 0),
    -- A decided lot must record who/when decided (HU06.2).
    CONSTRAINT lots_decision_audit
        CHECK (status = 'pendiente_revision'
               OR (decided_by IS NOT NULL AND decided_at IS NOT NULL))
);

-- =============================================================================
-- INVENTORY
-- =============================================================================
-- Stock is tracked per lot (HU11 "cuántos lentes hay por lote"). The lens
-- reference is reachable through the lot. One inventory row per lot.
-- Only units in lots with status 'autorizado' count as available stock.
-- -----------------------------------------------------------------------------

CREATE TABLE lot_inventory (
    lot_id         UUID        PRIMARY KEY REFERENCES lots (id) ON DELETE CASCADE,
    quantity       INTEGER     NOT NULL DEFAULT 0,    -- units currently in warehouse
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT lot_inventory_quantity_nonneg CHECK (quantity >= 0)
);

-- =============================================================================
-- LENS REQUESTS FROM POINTS OF SALE  (HU07)
-- =============================================================================

CREATE TABLE lens_requests (
    id               UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    request_number   BIGINT      GENERATED ALWAYS AS IDENTITY,  -- human-facing number
    point_of_sale_id UUID        NOT NULL REFERENCES points_of_sale (id) ON DELETE RESTRICT,
    lens_id          UUID        NOT NULL REFERENCES lenses (id) ON DELETE RESTRICT,
    quantity         INTEGER     NOT NULL,
    status           lens_request_status NOT NULL DEFAULT 'solicitada',
    requested_by     UUID        REFERENCES users (id) ON DELETE SET NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT lens_requests_quantity_positive CHECK (quantity > 0),
    CONSTRAINT lens_requests_request_number_key UNIQUE (request_number)
);

-- =============================================================================
-- RESTOCK ORDERS  (HU08)
-- =============================================================================
-- Admin de puntos de venta compares a point's inventory with the warehouse
-- and builds an order of references + quantities to restock a point of sale.
-- -----------------------------------------------------------------------------

CREATE TABLE restock_orders (
    id                   UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    order_number         BIGINT      GENERATED ALWAYS AS IDENTITY,
    destination_pos_id   UUID        NOT NULL REFERENCES points_of_sale (id) ON DELETE RESTRICT,
    status               restock_order_status NOT NULL DEFAULT 'pendiente_alistamiento',
    created_by           UUID        REFERENCES users (id) ON DELETE SET NULL,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT restock_orders_order_number_key UNIQUE (order_number)
);

CREATE TABLE restock_order_items (
    id              UUID    PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id        UUID    NOT NULL REFERENCES restock_orders (id) ON DELETE CASCADE,
    lens_id         UUID    NOT NULL REFERENCES lenses (id) ON DELETE RESTRICT,
    quantity        INTEGER NOT NULL,

    CONSTRAINT restock_order_items_quantity_positive CHECK (quantity > 0),
    CONSTRAINT restock_order_items_unique_lens UNIQUE (order_id, lens_id)
);

-- =============================================================================
-- POINT-OF-SALE INVENTORY  (needed to compare with warehouse in HU08)
-- =============================================================================

CREATE TABLE pos_inventory (
    point_of_sale_id UUID        NOT NULL REFERENCES points_of_sale (id) ON DELETE CASCADE,
    lens_id          UUID        NOT NULL REFERENCES lenses (id) ON DELETE RESTRICT,
    quantity         INTEGER     NOT NULL DEFAULT 0,
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),

    PRIMARY KEY (point_of_sale_id, lens_id),
    CONSTRAINT pos_inventory_quantity_nonneg CHECK (quantity >= 0)
);

-- =============================================================================
-- LOT HISTORY  (HU12)  &  DISPATCHES
-- =============================================================================
-- Chronological events for a lot, plus the record of dispatches to points of
-- sale (quantity sent, date, confirmed) so the history can show destinations.
-- -----------------------------------------------------------------------------

CREATE TABLE dispatches (
    id                 UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    lot_id             UUID        NOT NULL REFERENCES lots (id) ON DELETE RESTRICT,
    destination_pos_id UUID        NOT NULL REFERENCES points_of_sale (id) ON DELETE RESTRICT,
    restock_order_id   UUID        REFERENCES restock_orders (id) ON DELETE SET NULL,
    lens_request_id    UUID        REFERENCES lens_requests (id) ON DELETE SET NULL,
    quantity           INTEGER     NOT NULL,
    dispatched_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    confirmed          BOOLEAN     NOT NULL DEFAULT FALSE,
    confirmed_at       TIMESTAMPTZ,
    dispatched_by      UUID        REFERENCES users (id) ON DELETE SET NULL,

    CONSTRAINT dispatches_quantity_positive CHECK (quantity > 0)
);

CREATE TABLE lot_events (
    id            UUID           PRIMARY KEY DEFAULT gen_random_uuid(),
    lot_id        UUID           NOT NULL REFERENCES lots (id) ON DELETE CASCADE,
    event_type    lot_event_type NOT NULL,
    occurred_at   TIMESTAMPTZ    NOT NULL DEFAULT now(),
    performed_by  UUID           REFERENCES users (id) ON DELETE SET NULL,
    details       TEXT,
    -- Optional link to a dispatch for 'despacho' events.
    dispatch_id   UUID           REFERENCES dispatches (id) ON DELETE SET NULL
);

-- =============================================================================
-- INDEXES
-- =============================================================================

CREATE INDEX idx_users_role                ON users (role);
CREATE INDEX idx_users_point_of_sale       ON users (point_of_sale_id);
CREATE INDEX idx_lenses_sphere_cylinder    ON lenses (sphere, cylinder);
CREATE INDEX idx_lots_status               ON lots (status);
CREATE INDEX idx_lots_lens                 ON lots (lens_id);
CREATE INDEX idx_lots_import               ON lots (import_id);
CREATE INDEX idx_lots_location             ON lots (location_id);
CREATE INDEX idx_lens_requests_pos         ON lens_requests (point_of_sale_id);
CREATE INDEX idx_lens_requests_status      ON lens_requests (status);
CREATE INDEX idx_lens_requests_lens        ON lens_requests (lens_id);
CREATE INDEX idx_restock_orders_dest_pos   ON restock_orders (destination_pos_id);
CREATE INDEX idx_restock_orders_status     ON restock_orders (status);
CREATE INDEX idx_restock_order_items_order ON restock_order_items (order_id);
CREATE INDEX idx_pos_inventory_lens        ON pos_inventory (lens_id);
CREATE INDEX idx_dispatches_lot            ON dispatches (lot_id);
CREATE INDEX idx_dispatches_dest_pos       ON dispatches (destination_pos_id);
CREATE INDEX idx_lot_events_lot_time       ON lot_events (lot_id, occurred_at);
